def validate_refund(args, session):
    if args["orderId"] not in session["member_orders"]:
        raise ValueError("order not owned by this member")
    if not (0 < args["amount"] <= session["order_total"][args["orderId"]]):
        raise ValueError("amount out of range")
    return True

const orderStatusSchema = {
  type: 'object',
  properties: { orderId: { type: 'string', description: 'The order to look up status for.' } },
  required: ['orderId'],
};
const refundSchema = {
  type: 'object',
  description: 'Request a refund. Requires human confirmation; does not complete a refund.',
  properties: { orderId: { type: 'string' }, amount: { type: 'number' }, reason: { type: 'string' } },
  required: ['orderId', 'amount', 'reason'],
};

